import { afterEach, describe, expect, it, vi } from 'vitest';

import * as client from './client';
import {
  createIntent,
  deriveSealKey,
  fromBase64,
  keyIdentifier,
  seal,
  sealedPurpose,
  startWorkflow,
} from './adminManagement';

afterEach(() => vi.restoreAllMocks());

// Generated by cloud_agent_shared.deployment_contract (Python): a private key,
// a box it sealed and the identifier of a known secret. Opening the box here
// proves the browser derives the same key from the same format.
const VECTOR = {
  pkcs8:
    'MIGHAgEAMBMGByqGSM49AgEGCCqGSM49AwEHBG0wawIBAQQgp2ojdu2qTFKx+M+vDwqW20zgeJVq3QuuDRrTUw+TYnShRANCAATkUJzKppy4bhwgDe6FmKMYOkEVJuA2xvMdWIeTMTquXMD4lodMVTCJWRs7UmwKvqa8ragWXFjvyyOnPlQfRbia',
  public:
    'BORQnMqmnLhuHCAN7oWYoxg6QRUm4DbG8x1Yh5MxOq5cwPiWh0xVMIlZGztSbAq+prytqBZcWO/LI6c+VB9FuJo=',
  box: {
    v: 1 as const,
    epk: 'BDELMGDDd8LSrWO3bnB782QdKaRkojxHufMxzEGff0m4q8UrkLonNN3NiHleXF2pr8J1d+OvjijGiUmxmCh2DnY=',
    iv: 'j9zNjhDmeOOBwveN',
    ct: 'fNf+LQpovdZiYc6+xVFMoz6BClc9QFmsH4HdEs1FR36FM87YLquADxoipcn4QjpUGQ==',
  },
  purpose: 'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa:AGENT_DATABASE_URL',
  plaintext: 'postgresql://user:secret@db/agent',
};

async function open(
  box: { epk: string; iv: string; ct: string },
  purpose: string,
): Promise<string> {
  const privateKey = await crypto.subtle.importKey(
    'pkcs8',
    fromBase64(VECTOR.pkcs8),
    { name: 'ECDH', namedCurve: 'P-256' },
    false,
    ['deriveBits'],
  );
  const peer = await crypto.subtle.importKey(
    'raw',
    fromBase64(box.epk),
    { name: 'ECDH', namedCurve: 'P-256' },
    false,
    [],
  );
  const shared = await crypto.subtle.deriveBits({ name: 'ECDH', public: peer }, privateKey, 256);
  const key = await deriveSealKey(shared, purpose);
  const plain = await crypto.subtle.decrypt(
    { name: 'AES-GCM', iv: fromBase64(box.iv), additionalData: new TextEncoder().encode(purpose) },
    key,
    fromBase64(box.ct),
  );
  return new TextDecoder().decode(plain);
}

describe('sealing values to a deployment agent', () => {
  it('opens a value the Python contract sealed', async () => {
    expect(await open(VECTOR.box, VECTOR.purpose)).toBe(VECTOR.plaintext);
  });

  it('seals a value the same way, bound to its purpose', async () => {
    const box = await seal(
      VECTOR.public,
      'new-value',
      sealedPurpose('a'.repeat(32), 'ADMIN_TOKEN'),
    );
    expect(box.v).toBe(1);
    expect(JSON.stringify(box)).not.toContain('new-value');
    expect(await open(box, `${'a'.repeat(32)}:ADMIN_TOKEN`)).toBe('new-value');
    await expect(open(box, `${'a'.repeat(32)}:OTHER`)).rejects.toThrow();
  });

  it('computes the identifier the processes report', async () => {
    expect(await keyIdentifier('an-example-secret-of-thirty-two-bytes')).toBe('6981a1aa41a2a666');
    expect(await keyIdentifier('')).toBe('');
  });
});

describe('deployment requests', () => {
  it('sends an intent with a fresh idempotency key and a workflow with its confirmation', async () => {
    const fetch = vi
      .spyOn(client, 'fetchWithAuth')
      .mockImplementation(
        async () => new Response('{}', { headers: { 'Content-Type': 'application/json' } }),
      );
    await createIntent('b'.repeat(32), {
      operation: 'restart_services',
      params: { services: ['web'] },
    });
    const body = JSON.parse(String((fetch.mock.calls[0][2] as RequestInit).body));
    expect(body.idempotency_key).toMatch(/^[0-9a-f]{32}$/);
    expect(body.sealed).toEqual({});
    await startWorkflow({ kind: 'root_key', params: { new_key_id: 'x' } });
    const workflow = JSON.parse(String((fetch.mock.calls[1][2] as RequestInit).body));
    expect(workflow.confirm).toBe('root_key');
    expect(fetch.mock.calls[1][1]).toBe('/admin/agent/deployments/workflows');
  });
});
